var qz={on:false},QLV="All";
function sh(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),x=a[i];a[i]=a[j];a[j]=x}return a}
function qok(q){return !q.w||!!findTok(q.w[0],q.w[1],q.w[2],q.w[3])}
function qs(t){return t[4].filter(qok)}
function qtext(q){var h=esc(q.t);if(q.w){var f=findTok(q.w[0],q.w[1],q.w[2],q.w[3]);h=h.replace("{w}",'<span class="ar" lang="ar" style="font-size:1.5rem">'+esc(f.T[f.i])+"</span>")}return h}
function menu(){
  qz={on:false};var S=ld("qla_sc",{});
  var h='<div class="row"><label for="lv">Level</label><select id="lv">'+["All","Beginner","Intermediate","Advanced"].map(function(l){return'<option'+(l===QLV?" selected":"")+">"+l+"</option>"}).join("")+'</select></div><button class="b" data-mix="1">Mixed test (10 questions)</button>';
  ["Arabic Grammar","Understanding the Quran"].forEach(function(g){
    var L=QT.filter(function(t){return t[3]===g&&(QLV==="All"||t[2]===QLV)});
    h+="<h3>"+g+"</h3>";if(!L.length)h+='<p class="tx">No topics at this level.</p>';
    L.forEach(function(t){var last=(S[t[0]]||[])[0];h+='<div class="box row"><span style="flex:1"><b>'+esc(t[1])+'</b><br><span class="tx">'+t[2]+" · "+qs(t).length+" questions"+(last?" · last: "+last:"")+'</span></span><button class="b" data-t="'+t[0]+'">Start</button></div>'});
  });
  $("qz").innerHTML=h;
}
function startQuiz(force){if(!force&&qz.on)return;menu()}
function begin(base,title,id){qz={on:true,base:base,list:sh(base),i:0,sc:0,wrong:[],title:title,id:id,lock:false};drawQ()}
function drawQ(){
  if(qz.i>=qz.list.length)return result();
  var q=qz.list[qz.i];qz.lock=false;
  $("qz").innerHTML='<div class="box"><p class="tx">'+esc(qz.title)+" · Question "+(qz.i+1)+" of "+qz.list.length+"</p><b>"+qtext(q)+"</b>"+
  sh([0,1,2,3]).map(function(k){return'<button class="opt" data-a="'+k+'">'+esc(q.o[k])+"</button>"}).join("")+'<div id="fb" role="status"></div><div class="row"><button class="b alt" id="qmenu">Stop test</button></div></div>';
}
function answer(a){
  if(qz.lock)return;qz.lock=true;
  var q=qz.list[qz.i],ok=a===0;
  if(ok)qz.sc++;else qz.wrong.push(q);
  document.querySelectorAll("#qz .opt").forEach(function(b){var k=+b.dataset.a;if(k===0)b.classList.add("good");else if(k===a)b.classList.add("bad")});
  $("fb").innerHTML="<p><b>"+(ok?"Correct.":"Not quite.")+"</b> "+(ok?"":"The answer is: "+esc(q.o[0])+". ")+esc(q.e)+'</p><button class="b" id="nxt">'+(qz.i===qz.list.length-1?"See score":"Next")+"</button>";
}
function result(){
  var n=qz.list.length,pct=Math.round(qz.sc/n*100),S=ld("qla_sc",{}),prev=(S[qz.id]||[]).slice();
  S[qz.id]=[qz.sc+"/"+n+" ("+pct+"%)"].concat(prev).slice(0,5);sv("qla_sc",S);
  $("qz").innerHTML='<div class="box"><h3>'+esc(qz.title)+"</h3><h3>Score: "+qz.sc+" / "+n+" ("+pct+'%)</h3><p>Correct: '+qz.sc+" · Incorrect: "+(n-qz.sc)+"</p>"+
  (qz.wrong.length?"<b>Review of incorrect answers</b>"+qz.wrong.map(function(q){return"<p>"+qtext(q)+'<br><span class="tx">Answer: '+esc(q.o[0])+". "+esc(q.e)+"</span></p>"}).join(""):"<p>Excellent! Everything was correct.</p>")+
  (prev.length?'<p class="tx">Previous scores: '+prev.join(", ")+"</p>":"")+'<div class="row"><button class="b" id="qretake">Retake test</button><button class="b alt" id="qmenu">All topics</button></div></div>';
  qz.on=false;
}
$("qz").addEventListener("click",function(e){
  var t=e.target;
  if(t.dataset.t){var tp=QT.filter(function(x){return x[0]===t.dataset.t})[0];begin(qs(tp),tp[1],tp[0]);return}
  if(t.dataset.mix){var pool=[];QT.filter(function(x){return QLV==="All"||x[2]===QLV}).forEach(function(x){pool=pool.concat(qs(x))});begin(sh(pool).slice(0,10),"Mixed test ("+QLV+")","mix");return}
  if(t.id==="qmenu"){menu();return}
  if(t.id==="qretake"){if(qz.id==="mix"){var p2=[];QT.filter(function(x){return QLV==="All"||x[2]===QLV}).forEach(function(x){p2=p2.concat(qs(x))});begin(sh(p2).slice(0,10),qz.title,"mix")}else begin(qz.base,qz.title,qz.id);return}
  if(t.id==="nxt"){qz.i++;drawQ();return}
  if(t.dataset.a!==undefined)answer(+t.dataset.a);
});
$("qz").addEventListener("change",function(e){if(e.target.id==="lv"){QLV=e.target.value;menu()}});

/* ---------- Assistant (offline FAQ) ---------- */
var FAQ=[
[["ism","اسم"],"Ism means a noun-type word: it names a person, place, thing or quality. Example: رَبِّ (Rabb, Lord) in Al-Fatihah, Ayah 2.","اسم وہ لفظ ہے جو کسی شخص، جگہ، چیز یا صفت کا نام ہو۔ مثال: رَبِّ (رب) سورۃ الفاتحہ آیت 2 میں۔"],
[["fil","فعل"],"Fiʿl means a verb: it shows an action and its time. Example: نَعْبُدُ (we worship) in Al-Fatihah, Ayah 5.","فعل وہ لفظ ہے جس میں کام اور زمانہ پایا جائے۔ مثال: نَعْبُدُ (ہم عبادت کرتے ہیں) سورۃ الفاتحہ آیت 5 میں۔"],
[["harf","حرف"],"Harf means a particle. It does not give a full meaning alone. Example: the لِ in لِلَّهِ (for Allah) in Al-Fatihah, Ayah 2.","حرف وہ لفظ ہے جو اکیلا مکمل معنی نہیں دیتا۔ مثال: لِلَّهِ میں لِ (اللہ کے لیے) سورۃ الفاتحہ آیت 2 میں۔"],
[["fimazi","fimadi","madi","mazi","mudari","muzari","amr","tenses","فعلماضی","مضارع","فعلامر"],"A fiʿl has three forms: māḍī (past), muḍāriʿ (present or future) and amr (command). Example: نَعْبُدُ (we worship) is muḍāriʿ, and ٱهْدِنَا (guide us) is amr. Both are in Al-Fatihah (Ayah 5 and Ayah 6).","فعل کی تین صورتیں ہیں: ماضی (گزرا ہوا زمانہ)، مضارع (حال یا مستقبل) اور امر (حکم)۔ مثال: نَعْبُدُ مضارع ہے اور ٱهْدِنَا امر ہے۔ دونوں سورۃ الفاتحہ میں ہیں (آیت 5 اور آیت 6)۔"],
[["ismekhaas","ismekhas","ismeaam","ismeam","propernoun","commonnoun","اسمخاص","اسمعام"],"Ism-e-khaas is a proper noun: the name of one particular person or being (Allah, Musa, Maryam). Ism-e-aam is a common noun: the name of a whole kind (book, man, people). See Arabic Grammar, lesson Ism-e-Khaas and Ism-e-Aam, for Quranic examples.","اسمِ خاص کسی ایک معین شخص یا ذات کا نام ہے (اللہ، موسیٰ، مریم)۔ اسمِ عام پوری جنس کا نام ہے (کتاب، آدمی، لوگ)۔ قرآنی مثالوں کے لیے عربی گرامر میں اسمِ خاص اور اسمِ عام کا سبق دیکھیں۔"],
[["zameer","zamir","pronoun","ضمير","ضمیر"],"A zameer is a pronoun. Zameer marfūʿ munfasil (separate): huwa, humā, hum, hiya, hunna, anta, antumā, antum, anti, antunna, anā, naḥnu. Zameer muttasil is joined to another word, like the ka in rabbuka. See the Zameer lesson for Quranic examples.","ضمیر وہ لفظ ہے جو اسم کی جگہ آتا ہے۔ ضمیرِ مرفوع منفصل الگ لفظ ہوتی ہے: هو، هما، هم، هي، هن، أنت، أنتما، أنتم، أنتِ، أنتن، أنا، نحن۔ ضمیرِ متصل دوسرے لفظ سے جڑی ہوتی ہے، جیسے ربّك میں ك۔ قرآنی مثالوں کے لیے ضمیر کا سبق دیکھیں۔"],
[["ismeishara","ishara","demonstrative","اسماشارہ","اشارہ"],"Ism-e-ishara points to something: dhālika (that, far, masculine), tilka (that, far, feminine), hādhā (this, near, masculine), ulāʾika (those). See the Ism-e-Ishara lesson for Quranic examples.","اسمِ اشارہ سے کسی چیز کی طرف اشارہ کیا جاتا ہے: ذلك (وہ، دور، مذکر)، تلك (وہ، دور، مؤنث)، هذا (یہ، قریب، مذکر)، أولئك (وہ لوگ)۔ قرآنی مثالوں کے لیے اسمِ اشارہ کا سبق دیکھیں۔"],
[["harfejar","ismemajroor","ismemajrur","preposition","حرفجر","اسممجرور"],"Harf-e-jar (preposition) comes before a noun and puts it in jarr: min (from), ilā (to), ʿalā (on), fī (in), bi (with, by), li (for). The noun after it is the ism-e-majroor. See the Harf-e-Jar lesson for Quranic examples.","حرفِ جر اسم سے پہلے آ کر اسے جر (زیر) دیتا ہے: مِن، إلى، على، في، بِ، لِ۔ جس اسم کو جر ملے وہ اسمِ مجرور ہے۔ قرآنی مثالوں کے لیے حرفِ جر کا سبق دیکھیں۔"],
[["mushabbaha","mushabahabilfil","hurufmushabbaha","inna","laalla","laita","kaanna","حروفمشبہ"],"Huruf mushabbaha bil-fiʿl are inna, anna, ka-anna, lākinna, laita and laʿalla. They enter a nominal sentence: the first noun becomes their ism (manṣūb) and the second stays marfūʿ as their khabar. See the lesson for Quranic examples.","حروفِ مشبہ بالفعل: إنّ، أنّ، كأنّ، لكنّ، ليت، لعلّ۔ یہ جملہ اسمیہ پر آتے ہیں: پہلا اسم ان کا اسم (منصوب) اور دوسرا ان کی خبر (مرفوع) رہتی ہے۔ قرآنی مثالوں کے لیے سبق دیکھیں۔"],
[["mawsuf","mausuf","mosuf","moosuf","mawsoof","mausoof","moosoof","mosoof","moosof","mosof","sifat","sifaat","نعت","موصوف","صفت"],"Mawsuf is the noun being described. Sifat is the word that describes it. The sifat comes after the mawsuf and matches it in four things: gender (masculine or feminine), number (singular, dual, plural), case (raf, naṣb, jarr) and definiteness (with or without al-). Example: رَجُلٌ كَرِيمٌ (a generous man). Rajul is the mawsuf and karīm is the sifat.","موصوف وہ اسم ہے جس کی صفت بیان کی جائے اور صفت وہ لفظ ہے جو اس کی خوبی یا حالت بتائے۔ صفت موصوف کے بعد آتی ہے اور چار باتوں میں اس کے مطابق ہوتی ہے: مذکر/مؤنث، واحد/تثنیہ/جمع، اعراب (رفع، نصب، جر) اور معرفہ/نکرہ۔ مثال: رَجُلٌ كَرِيمٌ (سخی آدمی)۔ رجل موصوف اور كريم صفت ہے۔"],
[["mubtada","mubtadaa","khabar","jumlaismiya","jumlaismia","nominalsentence","مبتدا","خبر","جملہاسمیہ"],"A jumla ismiya (nominal sentence) begins with a noun. The first part is the mubtada’ (what is talked about) and the second part is the khabar (what is said about it). Both are usually marfūʿ. Example: الْعِلْمُ نُورٌ (knowledge is light). Al-ʿilmu is the mubtada’ and nūrun is the khabar.","جملہ اسمیہ اسم سے شروع ہوتا ہے۔ پہلا حصہ مبتدا ہے (جس کے بارے میں بات ہو) اور دوسرا خبر ہے (جو اس کے بارے میں بتایا جائے)۔ دونوں عموماً مرفوع ہوتے ہیں۔ مثال: الْعِلْمُ نُورٌ (علم نور ہے)۔ العلم مبتدا اور نور خبر ہے۔"],
[["fail","faail","mafool","maful","mafulbihi","jumlafiliya","jumlafiliyah","verbalsentence","فاعل","مفعول","جملہفعلیہ"],"A jumla fiʿliya (verbal sentence) begins with a fiʿl. The fāʿil is the doer and is marfūʿ. The mafʿūl bihi is what the action falls on and is manṣūb. Example: كَتَبَ الطَّالِبُ الدَّرْسَ (the student wrote the lesson). Kataba is the fiʿl, al-ṭālibu is the fāʿil and al-darsa is the mafʿūl bihi.","جملہ فعلیہ فعل سے شروع ہوتا ہے۔ فاعل کام کرنے والا ہے اور مرفوع ہوتا ہے۔ مفعول بہ وہ ہے جس پر کام واقع ہو اور وہ منصوب ہوتا ہے۔ مثال: كَتَبَ الطَّالِبُ الدَّرْسَ (طالب علم نے سبق لکھا)۔ كتب فعل، الطالب فاعل اور الدرس مفعول بہ ہے۔"],
[["ismefail","ismfail","activeparticiple","اسمفاعل"],"Ism-e-fāʿil is a noun made from a verb that names the one who does the action. From a three-letter root it follows the pattern فَاعِل. Example: كَاتِب (writer) from كَتَبَ (he wrote).","اسمِ فاعل وہ اسم ہے جو فعل سے بنتا ہے اور کام کرنے والے کو بتاتا ہے۔ تین حرفی مادے سے اس کا وزن فَاعِل ہوتا ہے۔ مثال: كَاتِب (لکھنے والا) كَتَبَ سے۔"],
[["irab","iraab","marfu","marfoo","mansub","mansoob","majroor","majrur","raf","nasb","jarr","اعراب","مرفوع","منصوب","مجرور"],"Iʿrāb is the change in the ending of a word that shows its job in the sentence. Raf (marfūʿ) usually has a ḍamma and is used for the subject (mubtada’, khabar, fāʿil). Naṣb (manṣūb) usually has a fatḥa and is used for the object (mafʿūl bihi). Jarr (majrūr) usually has a kasra and comes after a harf-e-jar or as muḍāf ilayh.","اعراب لفظ کے آخر کی وہ تبدیلی ہے جو جملے میں اس کا کردار بتاتی ہے۔ رفع (مرفوع) عموماً پیش سے ہوتا ہے اور مبتدا، خبر اور فاعل کے لیے آتا ہے۔ نصب (منصوب) عموماً زبر سے ہوتا ہے اور مفعول بہ کے لیے آتا ہے۔ جر (مجرور) عموماً زیر سے ہوتا ہے اور حرفِ جر کے بعد یا مضاف الیہ بن کر آتا ہے۔"],
[["mudaf","muzaf","mudafilayh","mudafilaih","idafa","izafat","izafa","مضاف"],"Idāfa joins two nouns. The first is the muḍāf and the second is the muḍāf ilayh, which is always majrūr. The muḍāf loses its tanwīn and does not take al-. Example: كِتَابُ الطَّالِبِ (the student’s book).","اضافت دو اسموں کو ملاتی ہے۔ پہلا مضاف اور دوسرا مضاف الیہ ہوتا ہے جو ہمیشہ مجرور ہوتا ہے۔ مضاف پر تنوین اور ال نہیں آتے۔ مثال: كِتَابُ الطَّالِبِ (طالب علم کی کتاب)۔"],
[["filnaqis","filnaqisa","afalnaqisa","afalenaqisa","naqis","naqisa","nakis","kanawaakhawatuha","kanaandsisters","فعلناقص","افعالناقصہ","ناقص","كانواخواتها"],"‘Fiʿl nāqiṣ’ has two meanings. 1) In naḥw (syntax), the afʿāl nāqiṣa are kāna and its sisters: kāna (was), aṣbaḥa, amsā, aḍḥā, ẓalla, bāta, ṣāra (became), laysa (is not), mā zāla, mā bariḥa, mā fatiʾa, mā infakka (still continuing) and mā dāma (as long as). They are called defective because the doer alone does not complete their meaning: they enter a nominal sentence. The mubtada’ stays marfūʿ and is called the ism of kāna; the khabar becomes manṣūb and is called the khabar of kāna. Example: وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا (Surah 4, Ayah 96): kāna is the fiʿl nāqiṣ, Allāhu is its ism (marfūʿ), ghafūran is its khabar (manṣūb) and raḥīman is a second khabar. Another example: وَكَانَ رَبُّكَ قَدِيرًا (Surah 25, Ayah 54). 2) In ṣarf (morphology), a nāqiṣ verb has a weak letter (wāw or yāʾ) as its last root letter: for example دَعَا (he called, root د ع و) is nāqiṣ wāwī and رَمَى (he threw, root ر م ي) is nāqiṣ yāʾī.","‘فعلِ ناقص’ کے دو مفہوم ہیں۔ 1) نحو میں افعالِ ناقصہ سے مراد كان اور اس کی بہنیں ہیں: كان، أصبح، أمسى، أضحى، ظل، بات، صار، ليس، ما زال، ما برح، ما فتئ، ما انفك اور ما دام۔ انہیں ناقص اس لیے کہتے ہیں کہ صرف فاعل سے ان کا معنی پورا نہیں ہوتا؛ یہ جملہ اسمیہ پر آتے ہیں۔ مبتدا مرفوع رہتا ہے اور اسمِ كان کہلاتا ہے، اور خبر منصوب ہو جاتی ہے اور خبرِ كان کہلاتی ہے۔ مثال: وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا (سورۃ 4, آیت 96): كان فعلِ ناقص ہے، اللَّهُ اس کا اسم (مرفوع)، غفورا خبر (منصوب) اور رحيما دوسری خبر ہے۔ دوسری مثال: وَكَانَ رَبُّكَ قَدِيرًا (سورۃ 25, آیت 54)۔ 2) صرف میں ناقص اس فعل کو کہتے ہیں جس کے مادے کا آخری حرف حرفِ علت (واو یا یاء) ہو: جیسے دَعَا (اس نے پکارا، مادہ د ع و) ناقص واوی اور رَمَى (اس نے پھینکا، مادہ ر م ي) ناقص یائی ہے۔"],
[["fillazim","filmutaaddi","filmutadi","mutaaddi","mutaadi","transitive","intransitive","فعللازم","فعلمتعدی","متعدی"],"A fiʿl lāzim (intransitive) needs only a doer and takes no direct object, for example جَلَسَ (he sat). A fiʿl mutaʿaddī (transitive) takes a direct object (mafʿūl bihi), for example كَتَبَ (he wrote something).","فعلِ لازم صرف فاعل چاہتا ہے اور اس کا مفعول بہ نہیں ہوتا، جیسے جَلَسَ (وہ بیٹھا)۔ فعلِ متعدی مفعول بہ لیتا ہے، جیسے كَتَبَ (اس نے لکھا)۔"],
[["filmaruf","filmajhul","majhul","passive","naibulfail","فعلمعروف","فعلمجہول","مجہول","نائبفاعل"],"A fiʿl maʿrūf (active) names the doer: كَتَبَ الطَّالِبُ (the student wrote). A fiʿl majhūl (passive) does not name the doer, and the object takes its place, called nāʾib al-fāʿil (marfūʿ): كُتِبَ الدَّرْسُ (the lesson was written).","فعلِ معروف میں کام کرنے والا مذکور ہوتا ہے: كَتَبَ الطَّالِبُ (طالب علم نے لکھا)۔ فعلِ مجہول میں فاعل مذکور نہیں ہوتا اور مفعول اس کی جگہ آتا ہے جسے نائبِ فاعل (مرفوع) کہتے ہیں: كُتِبَ الدَّرْسُ (سبق لکھا گیا)۔"],
[["filsahih","filmutal","muatal","mutal","ajwaf","lafif","فعلصحیح","فعلمعتل","معتل","اجوف","لفیف"],"A fiʿl ṣaḥīḥ (sound) has no weak letter (و ا ي) in its root, for example كَتَبَ. A fiʿl muʿtall (weak) has one or more weak letters. Its types: mithāl (first letter weak, e.g. وَعَدَ), ajwaf (middle weak, e.g. قَالَ), nāqiṣ (last weak, e.g. دَعَا) and lafīf (two weak letters, e.g. وَقَى).","فعلِ صحیح کے مادے میں حرفِ علت (و ا ي) نہیں ہوتا، جیسے كَتَبَ۔ فعلِ معتل میں ایک یا زیادہ حروفِ علت ہوتے ہیں۔ اقسام: مثال (پہلا حرف علت، جیسے وَعَدَ)، اجوف (درمیانی حرف علت، جیسے قَالَ)، ناقص (آخری حرف علت، جیسے دَعَا) اور لفیف (دو حروفِ علت، جیسے وَقَى)۔"],
[["whatisquran","meaningofquran","namesofquran","qurankenaam","qurankamatlab","qurankyahai","qurankyahota","furqan","قرآنکیاہے","قرآنکےنام","قرآنکامعنی"],"The Quran is the word of Allah revealed to Prophet Muhammad ﷺ through Angel Jibrīl, preserved in the Mushaf and recited as worship. The word qurʾān comes from the root q-r-ʾ (to read, to recite). The Quran itself uses other names, such as al-Furqān (Surah 25, Ayah 1), al-Dhikr (Surah 15, Ayah 9), al-Kitāb, al-Tanzīl and al-Hudā.","قرآن مجید اللہ کا کلام ہے جو حضرت محمد ﷺ پر حضرت جبریل علیہ السلام کے ذریعے نازل ہوا، مصحف میں محفوظ ہے اور اس کی تلاوت عبادت ہے۔ لفظ قرآن مادہ ق ر ء (پڑھنا) سے ہے۔ قرآن کے دوسرے نام: الفرقان (سورۃ 25، آیت 1)، الذکر (سورۃ 15، آیت 9)، الکتاب، التنزیل اور الہدیٰ۔"],
[["wahi","wahy","revelation","firstrevelation","pehliwahi","hira","غارحرا","وحی"],"Wahi means a quick, hidden communication from Allah. The Quran says Allah speaks to a human being by wahi (inspiration), from behind a veil, or by sending a messenger angel (Surah 42, Ayah 51). The first revelation was the opening ayat of Surah Al-ʿAlaq (Surah 96, Ayahs 1 to 5), in the cave of Ḥirāʾ.","وحی اللہ کی طرف سے تیز اور مخفی پیغام رسانی کو کہتے ہیں۔ قرآن بتاتا ہے کہ اللہ انسان سے وحی کے ذریعے، پردے کے پیچھے سے، یا قاصد فرشتہ بھیج کر کلام کرتا ہے (سورۃ 42، آیت 51)۔ پہلی وحی سورۃ العلق کی ابتدائی آیات تھیں (سورۃ 96، آیات 1 تا 5)، غارِ حرا میں۔"],
[["periodofrevelation","23years","tadrij","gradualrevelation","nuzulequran","laylatulqadr","shabeqadr","نزولقرآن","شبقدر","لیلةالقدر"],"The Quran was revealed gradually over about 23 years: roughly 13 years in Makkah and 10 in Madinah. The Quran gives a reason: to strengthen the heart of the Prophet ﷺ and to recite it in stages (Surah 25, Ayah 32), and so it could be read to people slowly (Surah 17, Ayah 106). It also says it was sent down in Ramadan, in a blessed night (Surah 2, Ayah 185; Surah 44, Ayah 3; Surah 97, Ayah 1). Scholars discuss how this relates to the gradual revelation.","قرآن تقریباً 23 سال میں بتدریج نازل ہوا: تقریباً 13 سال مکہ میں اور 10 سال مدینہ میں۔ قرآن اس کی وجہ بتاتا ہے: نبی ﷺ کے دل کو مضبوط کرنا اور مرحلہ وار پڑھنا (سورۃ 25، آیت 32)، اور تاکہ لوگوں کو ٹھہر ٹھہر کر پڑھ کر سنایا جائے (سورۃ 17، آیت 106)۔ یہ بھی بتایا گیا کہ رمضان کی ایک مبارک رات میں اتارا گیا (سورۃ 2، آیت 185؛ سورۃ 44، آیت 3؛ سورۃ 97، آیت 1)۔ علماء اس کا بتدریج نزول سے تعلق بیان کرتے ہیں۔"],
[["makki","madani","makkimadani","makkivsmadani","مکی","مدنی"],"A common definition: Makki surahs were revealed before the Hijrah and Madani surahs after it (some scholars define it by place). Makki surahs usually stress tawḥīd, prophethood, the Hereafter and morals, with shorter ayat. Madani surahs usually include laws (family, trade, war and peace), the Muslim community and the People of the Book, with longer ayat. Lists commonly count about 86 Makki and 28 Madani surahs, but a few surahs are disputed. Example: Al-Mulk is Makki; Al-Baqarah is Madani.","عام تعریف: مکی سورتیں ہجرت سے پہلے اور مدنی سورتیں ہجرت کے بعد نازل ہوئیں (بعض علماء مقامِ نزول سے تعریف کرتے ہیں)۔ مکی سورتوں میں عموماً توحید، رسالت، آخرت اور اخلاق پر زور ہوتا ہے اور آیات چھوٹی ہوتی ہیں۔ مدنی سورتوں میں عموماً احکام (خاندان، تجارت، جنگ و صلح)، مسلم معاشرہ اور اہلِ کتاب کا ذکر ہوتا ہے اور آیات لمبی ہوتی ہیں۔ فہرستوں میں تقریباً 86 مکی اور 28 مدنی سورتیں شمار ہوتی ہیں، مگر چند سورتوں میں اختلاف ہے۔ مثال: الملک مکی ہے؛ البقرہ مدنی ہے۔"],
[["jamquran","jamaquran","jamequran","jamaequran","jamekquran","jamulquran","compilationofquran","compilation","mushaf","usmani","uthmani","zaydbinthabit","جمعقرآن","جمعالقرآن","مصحف"],"The compilation (jamʿ) of the Quran happened in three stages. 1) Time of the Prophet ﷺ: many Companions memorised it, and scribes of revelation (such as Zayd ibn Thābit) wrote it on leather, bones, palm leaves and stones. 2) Time of Abū Bakr: after many memorisers were martyred at Yamāma, ʿUmar advised collecting it, and Zayd ibn Thābit gathered the written pieces into one set of sheets (ṣuḥuf). 3) Time of ʿUthmān: copies were made from those sheets and sent to major cities to keep the text and recitation uniform. This is the ʿUthmānī Mushaf.","جمعِ قرآن تین مراحل میں ہوا۔ 1) عہدِ نبوی ﷺ: بہت سے صحابہ نے حفظ کیا اور کاتبینِ وحی (جیسے زید بن ثابت) نے چمڑے، ہڈیوں، کھجور کی شاخوں اور پتھروں پر لکھا۔ 2) عہدِ ابوبکر: جنگِ یمامہ میں کئی حفاظ شہید ہوئے تو عمر نے جمع کرنے کا مشورہ دیا اور زید بن ثابت نے لکھے ہوئے ٹکڑے ایک مجموعے (صحف) میں جمع کیے۔ 3) عہدِ عثمان: ان صحف سے نسخے تیار کر کے بڑے شہروں کو بھیجے گئے تاکہ متن اور قراءت یکساں رہے۔ یہ مصحفِ عثمانی ہے۔"],
[["howmanysurah","howmanyayat","howmanyjuz","juz","para","manzil","surahs","longestsurah","shortestsurah","longestayah","kitnisurat","kitniayat","kitneparay","kitnisurah","kitnesurah","kitnesurat","kitnisuratain","kitniayatain","kitniayaat","kitneayat","سورتیں","پارے","منزل","آیاتکیتعداد"],"The Quran has 114 surahs, 30 juz (para) and 7 manzils. In the count used by this app (Tanzil, Ḥafṣ) it has 6236 ayat, which includes the Bismillah of Al-Fatihah; counting traditions differ slightly. Al-Fatihah is the first surah and An-Nās the last. The longest surah is Al-Baqarah (286 ayat). The shortest in ayat are Al-ʿAṣr, Al-Kawthar and An-Naṣr (3 ayat each). The longest ayah is Surah 2, Ayah 282. To find the ayat of a surah, ask for example: Surah 67.","قرآن میں 114 سورتیں، 30 پارے (جزء) اور 7 منزلیں ہیں۔ اس ایپ کی گنتی (Tanzil، حفص) کے مطابق 6236 آیات ہیں جن میں سورۃ الفاتحہ کی بسم اللہ بھی شامل ہے؛ گنتی کے طریقوں میں تھوڑا فرق ہے۔ پہلی سورت الفاتحہ اور آخری الناس ہے۔ سب سے لمبی سورت البقرہ (286 آیات) ہے۔ آیات کے لحاظ سے سب سے چھوٹی سورتیں العصر، الکوثر اور النصر (تین تین آیات) ہیں۔ سب سے لمبی آیت سورۃ 2، آیت 282 ہے۔ کسی سورت کی آیات جاننے کے لیے مثلاً پوچھیں: Surah 67۔"],
[["preservation","preserved","hifazat","hifazatequran","hifz","hafiz","huffaz","tahreef","حفاظت","حفظ"],"Allah promises to protect the Quran (Surah 15, Ayah 9). It has been preserved through memorisation (huffāẓ) and writing together, and passed on by tawātur: by so many people in every generation that agreement on a falsehood is not possible. Differences in qirāʾāt are authentic recitation modes, not changes to the text.","اللہ نے قرآن کی حفاظت کا وعدہ فرمایا (سورۃ 15، آیت 9)۔ یہ حفظ (حفاظ) اور کتابت دونوں کے ذریعے محفوظ رہا اور تواتر سے منتقل ہوا، یعنی ہر دور میں اتنے لوگوں سے کہ جھوٹ پر اتفاق ممکن نہیں۔ قراءات کا فرق مستند طریقہ ہائے تلاوت ہے، متن میں تبدیلی نہیں۔"],
[["themesofquran","maintheme","mazameen","mazameenequran","purposeofquran","maqsad","موضوعات","مضامین","مقصدقرآن"],"Main themes of the Quran: tawḥīd (oneness of Allah), risāla (prophethood), ākhira (the Hereafter and accountability), guidance for personal and social life (worship, morals, family, justice), stories of earlier prophets and nations as lessons (qaṣaṣ), and reflection on Allah’s signs in creation. Makki surahs focus more on belief; Madani surahs add more laws and community matters.","قرآن کے بنیادی موضوعات: توحید، رسالت، آخرت اور جواب دہی، انفرادی و اجتماعی زندگی کی رہنمائی (عبادت، اخلاق، خاندان، عدل)، سابقہ انبیاء اور قوموں کے واقعات بطور عبرت (قصص)، اور کائنات میں اللہ کی نشانیوں پر غور۔ مکی سورتوں میں عقیدے پر زیادہ زور ہے اور مدنی سورتوں میں احکام اور معاشرتی امور زیادہ ہیں۔"],
[["tafsir","tafseer","tafsirbilmathur","tafsirbilrai","bilmathur","bilrai","tawil","tarjuma","tarjumah","booksoftafsir","tafheem","maariful","ibnkathir","tabari","jalalayn","qurtubi","تفسیر","تاویل","ترجمہ"],"Tafsīr is the explanation of the meaning of the Quran. Taʾwīl means interpretation or final meaning (used in different ways by scholars). Tarjuma is translation, which is not the same as tafsir. Types: tafsīr bil-maʾthūr (based on narration: the Quran explained by the Quran, the Sunnah, the Companions and the Successors) and tafsīr bil-raʾy (based on informed reasoning, accepted when it follows the rules of Arabic and the sources). Well-known books: al-Ṭabarī, Ibn Kathīr, al-Qurṭubī, al-Rāzī, al-Jalālayn; in Urdu: Maʿārif al-Qurʾān, Tafhīm al-Qurʾān, Bayān al-Qurʾān, Tadabbur-e-Qurʾān, Ḍiyāʾ al-Qurʾān.","تفسیر قرآن کے معنی کی وضاحت ہے۔ تاویل کا مطلب تعبیر یا انجامی معنی ہے (علماء اسے مختلف انداز سے استعمال کرتے ہیں)۔ ترجمہ تفسیر کے برابر نہیں ہوتا۔ اقسام: تفسیر بالماثور (روایات پر مبنی: قرآن کی تفسیر قرآن سے، سنت سے، صحابہ اور تابعین سے) اور تفسیر بالرائے (علمی غور و فکر پر مبنی، جو عربی کے قواعد اور مآخذ کے مطابق ہو)۔ معروف کتب: الطبری، ابن کثیر، القرطبی، الرازی، الجلالین؛ اردو میں: معارف القرآن، تفہیم القرآن، بیان القرآن، تدبرِ قرآن، ضیاء القرآن۔"],
[["asbabunnuzul","asbabenuzul","asbabnuzul","shanenuzul","reasonsofrevelation","اسبابنزول","شاننزول"],"Asbāb al-nuzūl are the events or questions that led to the revelation of an ayah. They help us understand the context. Not every ayah has a reported sabab, and the reports must be authentic. A common principle is that the lesson is taken from the general wording of the ayah, not only from the specific incident.","اسبابِ نزول وہ واقعات یا سوالات ہیں جن کے سبب کوئی آیت نازل ہوئی۔ ان سے سیاق سمجھنے میں مدد ملتی ہے۔ ہر آیت کا سببِ نزول منقول نہیں ہوتا اور روایات کا مستند ہونا ضروری ہے۔ ایک معروف اصول ہے کہ سبق آیت کے عمومی الفاظ سے لیا جاتا ہے، صرف خاص واقعے سے نہیں۔"],
[["muhkam","mutashabih","mutashabihat","muhkamat","محکم","متشابہ"],"Surah 3, Ayah 7 says the Quran has muḥkamāt (clear verses, the foundation of the Book) and others that are mutashābihāt (verses whose meaning is less clear, such as some matters of the unseen). The ayah warns against following the unclear ones to create confusion; they should be understood in light of the clear ones. Scholars differ on some details, so ask a qualified teacher.","سورۃ 3، آیت 7 بتاتی ہے کہ قرآن میں محکمات (واضح آیات، کتاب کی بنیاد) ہیں اور دوسری متشابہات (جن کا مطلب کم واضح ہے، جیسے بعض غیب کی باتیں)۔ آیت خبردار کرتی ہے کہ غیر واضح آیات کے پیچھے پڑ کر فتنہ نہ پھیلایا جائے؛ انہیں محکمات کی روشنی میں سمجھا جائے۔ بعض تفصیلات میں علماء کا اختلاف ہے، اس لیے کسی مستند استاد سے پوچھیں۔"],
[["naskh","nasikh","mansukh","abrogation","ناسخ","منسوخ","نسخ"],"Naskh means abrogation: a later ruling replacing an earlier one. Many scholars accept naskh in a limited number of cases, while some limit it more strictly or deny it in the Quran. The number of cases is disputed. This topic should be studied with a qualified teacher.","نسخ کا مطلب ہے بعد کے حکم کا پہلے حکم کی جگہ لینا۔ بہت سے علماء محدود مقامات پر نسخ مانتے ہیں، جبکہ بعض اسے زیادہ سختی سے محدود کرتے ہیں یا قرآن میں نہیں مانتے۔ مقامات کی تعداد میں اختلاف ہے۔ اس موضوع کو کسی مستند استاد سے پڑھنا چاہیے۔"],
[["qirat","qiraat","qiraah","hafs","warsh","sevenahruf","sabaahruf","ahruf","قرات","قراءات","سبعہاحرف","احرف"],"Qirāʾāt are authentic ways of reciting the Quran, each with a chain going back to the Prophet ﷺ. Ten qirāʾāt are well known. The most widespread today is Ḥafṣ ʿan ʿĀṣim (used in Pakistan, the Middle East and most of the world); Warsh ʿan Nāfiʿ is common in North and West Africa. The ‘seven aḥruf’ mentioned in hadith are understood by scholars in several ways and are not simply the seven qirāʾāt.","قراءات قرآن کی تلاوت کے مستند طریقے ہیں جن کی سند نبی ﷺ تک پہنچتی ہے۔ دس قراءات مشہور ہیں۔ آج سب سے زیادہ رائج حفص عن عاصم ہے (پاکستان، مشرقِ وسطیٰ اور دنیا کے بیشتر حصوں میں)؛ ورش عن نافع شمالی اور مغربی افریقہ میں عام ہے۔ حدیث میں مذکور ‘سبعہ احرف’ کی علماء نے کئی تشریحات کی ہیں اور یہ محض سات قراءات نہیں ہیں۔"],
[["ijaz","ijazulquran","miracle","miracleofquran","challenge","tahaddi","معجزہ","اعجاز","تحدی"],"Iʿjāz means the inimitability of the Quran. The Quran challenges those who doubt it to bring a surah like it (Surah 2, Ayah 23) and says that humans and jinn together could not produce the like of it (Surah 17, Ayah 88). Scholars point to its language and eloquence, its guidance, its consistency and its knowledge of the unseen as aspects of this.","اعجازِ قرآن کا مطلب قرآن کا بے مثل ہونا ہے۔ قرآن شک کرنے والوں کو اس جیسی ایک سورت لانے کا چیلنج دیتا ہے (سورۃ 2، آیت 23) اور فرماتا ہے کہ انسان اور جن مل کر بھی اس جیسا نہیں لا سکتے (سورۃ 17، آیت 88)۔ علماء اس کے پہلوؤں میں اس کی زبان اور فصاحت، رہنمائی، باہمی ہم آہنگی اور غیب کی خبروں کا ذکر کرتے ہیں۔"],
[["howtounderstand","understandquran","understandingofquran","understandingquran","quransamajhna","qurankosamajhna","kaisesamjh","kaisesamajh","qurankosamjh","qurankosamajh","rulesoftafsir","principlesoftafsir","usultafsir","فہمقرآن","قرآنسمجھنا","اصولتفسیر"],"Scholars advise: read with Arabic and its grammar in mind; read each ayah in its context and with other ayat on the same topic; use the authentic Sunnah, since the Prophet ﷺ was sent to explain the message (Surah 16, Ayah 44); consider the understanding of the Companions and trusted scholars; learn the occasion of revelation when it is known; and do not take one ayah out of context to reach a ruling. For rulings, ask a qualified scholar.","علماء کی رہنمائی: عربی زبان اور اس کی گرامر کو سامنے رکھ کر پڑھیں؛ ہر آیت کو اس کے سیاق اور اسی موضوع کی دوسری آیات کے ساتھ پڑھیں؛ مستند سنت سے مدد لیں کیونکہ نبی ﷺ پیغام کی وضاحت کے لیے بھیجے گئے (سورۃ 16، آیت 44)؛ صحابہ اور معتبر علماء کی فہم کو دیکھیں؛ جہاں معلوم ہو سببِ نزول جانیں؛ اور کسی ایک آیت کو سیاق سے کاٹ کر حکم نہ نکالیں۔ احکام کے لیے کسی مستند عالم سے پوچھیں۔"],
[["tajwid","tajweed","tartil","tarteel","makharij","recitation","adabequran","تجوید","ترتیل","آدابقرآن"],"Tajwīd is the science of reciting each letter correctly, from its point of articulation (makhraj) and with its qualities, following the rules of recitation. The Quran commands measured recitation, tartīl (Surah 73, Ayah 4). The best way to learn tajwīd is from a qualified teacher.","تجوید ہر حرف کو اس کے مخرج اور صفات کے ساتھ درست پڑھنے اور قواعدِ تلاوت پر عمل کرنے کا علم ہے۔ قرآن ٹھہر ٹھہر کر پڑھنے (ترتیل) کا حکم دیتا ہے (سورۃ 73، آیت 4)۔ تجوید سیکھنے کا بہترین طریقہ کسی مستند استاد سے سیکھنا ہے۔"],
[["ulumulquran","ulumalquran","ulumequran","quransciences","علومالقرآن","علومقرآن"],"ʿUlūm al-Qurʾān (sciences of the Quran) are the branches of knowledge about the Quran: revelation and its stages, Makki and Madani, the occasions of revelation, compilation, qirāʾāt, naskh, muḥkam and mutashābih, tafsir and its principles, and iʿjāz. You can ask me about each of these.","علوم القرآن قرآن سے متعلق علوم کی شاخیں ہیں: وحی اور اس کے مراحل، مکی و مدنی، اسبابِ نزول، جمعِ قرآن، قراءات، نسخ، محکم و متشابہ، تفسیر اور اس کے اصول، اور اعجاز۔ آپ مجھ سے ان میں سے ہر ایک کے بارے میں پوچھ سکتے ہیں۔"],
[["surahmulk","almulk","tabarak","suratulmulk","سورةالملک","سورۃالملک","سورہملک"],"Surah Al-Mulk is the 67th surah. It has 30 ayat and is Makki. Its main ideas are Allah’s sovereignty (mulk), His creation of life and death as a test of who is best in deeds (Surah 67, Ayah 2), the signs in creation, and accountability on the Day of Judgment.","سورۃ الملک 67 ویں سورت ہے۔ اس میں 30 آیات ہیں اور یہ مکی ہے۔ اس کے بنیادی مضامین: اللہ کی بادشاہی (ملک)، موت و حیات کی تخلیق بطور آزمائش کہ کون عمل میں بہتر ہے (سورۃ 67، آیت 2)، کائنات میں نشانیاں، اور قیامت کے دن جواب دہی۔"],
[["fatiha","alfatiha","fatihah","surahfatiha","فاتحہ","الفاتحہ"],"Surah Al-Fātiḥa is the first surah, with 7 ayat in the Tanzil count (the Bismillah is Ayah 1 there). It is Makki. It is also called Umm al-Kitāb and al-Sabʿ al-Mathānī. It contains praise of Allah, His lordship and mercy, His mastery of the Day of Judgment, worship and seeking help from Him alone, and the request for the straight path.","سورۃ الفاتحہ پہلی سورت ہے اور Tanzil کی گنتی میں اس کی 7 آیات ہیں (وہاں بسم اللہ آیت 1 ہے)۔ یہ مکی ہے۔ اسے ام الکتاب اور السبع المثانی بھی کہا جاتا ہے۔ اس میں اللہ کی حمد، اس کی ربوبیت اور رحمت، روزِ جزا کی ملکیت، صرف اسی کی عبادت اور مدد مانگنا، اور سیدھے راستے کی دعا ہے۔"]

];
var RUL=["halal","haram","fatwa","jaiz","hukum","hukm","hadith","hadees","حلال","حرام","فتوی","فتویٰ","حدیث"];
function nz(x){return x.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/ی/g,"ي").replace(/ک/g,"ك").replace(/[ہھە]/g,"ه").replace(/[\u064B-\u065F\u0670]/g,"").replace(/[ʿʾ’'`]/g,"").replace(/[-_.,?!؟،()]/g," ").replace(/\s+/g," ").trim()}
function say(c,t){var d=document.createElement("div");d.className=c;d.textContent=t;$("chat").appendChild(d)}
var lastKL=0;
var FILL=["kya","hai","hota","hoti","ho","what","is","are","the","a","an","of","ka","ki","ke","ko","me","mein","se","batao","bataye","bataen","explain","tell","about","means","meaning","matlab","کیا","ہے","ہوتا","ہوتی","کا","کی","کے","کو","میں","سے","بتاو","بتائیں"];
function best(v){
  var ws=nz(v).split(" "),c=ws.join(""),b=null,bl=0;
  FAQ.forEach(function(f){f[0].forEach(function(k){var kk=nz(k).replace(/ /g,"");var hit=kk.length>=4?c.indexOf(kk)>-1:ws.indexOf(kk)>-1;if(hit&&kk.length>bl){bl=kk.length;b=f}})});
  lastKL=bl;return b;
}
function ask(){
  var v=$("qi").value.trim();if(!v)return;if(v.length>300)v=v.slice(0,300);
  say("me",v);$("qi").value="";
  var sm=/(?:surah|surat|sura|سورة|سورۃ|سورہ)\s*(?:no\.?|number|نمبر)?\s*(\d{1,3})/i.exec(v);
  if(sm&&+sm[1]>=1&&+sm[1]<=114&&cnt.ar>0){var sn=+sm[1],k=0;while(Q.ar[sn+":"+(k+1)])k++;say("bot","Surah "+sn+" has "+k+" ayat."+(sn===1?" In Al-Fatihah the Bismillah is counted as Ayah 1.":"")+" Open the Quran tab to read it.");say("bot ur","سورۃ "+sn+" میں "+k+" آیات ہیں۔"+(sn===1?" سورۃ الفاتحہ میں بسم اللہ آیت 1 شمار ہوتی ہے۔":"")+" پڑھنے کے لیے قرآن والا ٹیب کھولیں۔");return}
  var ws=nz(v).split(" "),rul=RUL.some(function(k){return ws.indexOf(k)>-1}),f=rul?null:best(v);
  if(f){say("bot",f[1]);say("bot ur",f[2]);if(lastKL<=4&&ws.filter(function(x){return FILL.indexOf(x)<0}).length>=2){say("bot","Note: I answered the general topic. If you asked about something more specific, I may not have it yet, so please ask your teacher as well.");say("bot ur","نوٹ: میں نے عمومی موضوع کا جواب دیا ہے۔ اگر آپ نے کوئی زیادہ خاص سوال پوچھا ہے تو شاید وہ ابھی میرے پاس نہیں، اس لیے اپنے استاد سے بھی پوچھیں۔")}}
  else if(rul){say("bot","I cannot give religious rulings or check Hadith. Please ask a qualified scholar.");say("bot ur","میں دینی احکام یا حدیث کی تصدیق نہیں کر سکتا۔ براہِ کرم کسی مستند عالم سے پوچھیں۔")}
  else{say("bot","I do not have a verified answer for that. I only answer basic Arabic grammar from the lessons in this app. For the meaning of verses, tafsir or religious rulings, please ask a qualified teacher or scholar. You can try: Arabic grammar (ism, fiʿl, harf, zameer, mawsuf sifat, mubtada khabar, iʿrāb) or Quran studies (wahi, Makki and Madani, jamʿ al-Quran, tafsir, asbab al-nuzul, naskh, qirat, iʿjāz, how to understand the Quran, or Surah 67).");say("bot ur","اس سوال کا تصدیق شدہ جواب میرے پاس نہیں ہے۔ میں صرف اس ایپ کے اسباق کے مطابق بنیادی عربی گرامر بتا سکتا ہوں۔ آیات کے معنی، تفسیر یا دینی احکام کے لیے کسی مستند استاد یا عالم سے رجوع کریں۔")}
}
$("qs").onclick=ask;$("qi").onkeydown=function(e){if(e.key==="Enter")ask()};
say("bot","Ask me about Arabic grammar (ism, fiʿl, harf, zameer, mawsuf sifat, iʿrāb) or about understanding the Quran (wahi, Makki and Madani, jamʿ al-Quran, tafsir, asbab al-nuzul, naskh, qirat, iʿjāz), or ask for a surah such as Surah 67.");say("bot ur","عربی گرامر (اسم، فعل، حرف، ضمیر، موصوف صفت، اعراب) یا فہمِ قرآن (وحی، مکی و مدنی، جمعِ قرآن، تفسیر، اسبابِ نزول، نسخ، قراءات، اعجاز) کے بارے میں پوچھیں، یا کوئی سورت مثلاً Surah 67 پوچھیں۔");
